export function initTeamAnimations() {
  const teamEl = document.querySelector(".mwg008");
  if (!teamEl) return;

  // 1. Observer drag carousel
  const container = teamEl.querySelector(".mwg008-container");
  const cards = teamEl.querySelectorAll(".mwg008-card");

  if (container && cards.length && window.gsap && window.Observer) {
    let currentX = 0;
    const halfWidth = container.clientWidth / 2;
    cards.forEach((card, index) => {
      card.style.position = "relative";
      card.style.zIndex = cards.length - index;
    });

    const wrapX = window.gsap.utils.wrap(-halfWidth, 0);
    const quickX = window.gsap.quickTo(container, "x", {
      duration: 0.5,
      modifiers: { x: window.gsap.utils.unitize(wrapX) },
      ease: "power3"
    });
    const quickRot = window.gsap.quickTo(cards, "rotation", {
      duration: 0.8,
      ease: "power3"
    });

    window.Observer.create({
      target: container,
      type: "pointer,touch",
      onDrag: (e) => {
        currentX += e.deltaX;
        quickRot(0.002 * e.velocityX);
      },
      onRelease: () => quickRot(0),
      onStop: () => quickRot(0)
    });

    const tickerFn = (time, deltaTime) => {
      currentX -= deltaTime / 10;
      quickX(currentX);
    };
    window.gsap.ticker.add(tickerFn);
  }

  // 2. Pixelated image reveal on hover/click (8x8 pixel grid)
  const duration = 0.4;
  const gridSize = 8;
  const cellSize = 100 / gridSize;
  const revealItems = teamEl.querySelectorAll("[data-pixelated-image-reveal]");
  const isTouch = "ontouchstart" in window || navigator.maxTouchPoints > 0;

  revealItems.forEach((item) => {
    if (item.__pixImgInit) return;
    item.__pixImgInit = true;

    const grid = item.querySelector("[data-pixelated-image-reveal-grid]");
    const activeImg = item.querySelector("[data-pixelated-image-reveal-active]");
    if (!grid || !activeImg) return;

    grid.querySelectorAll(".pixelated-image-card__pixel").forEach((p) => p.remove());

    for (let r = 0; r < gridSize; r++) {
      for (let c = 0; c < gridSize; c++) {
        const pixel = document.createElement("div");
        pixel.classList.add("pixelated-image-card__pixel");
        pixel.style.width = `${cellSize}%`;
        pixel.style.height = `${cellSize}%`;
        pixel.style.left = `${c * cellSize}%`;
        pixel.style.top = `${r * cellSize}%`;
        grid.appendChild(pixel);
      }
    }

    const pixels = grid.querySelectorAll(".pixelated-image-card__pixel");
    const staggerTime = duration / pixels.length;
    let callTween = null;
    let isActive = false;

    const toggleReveal = (state) => {
      isActive = state;
      window.gsap.killTweensOf(pixels);
      if (callTween) callTween.kill();

      window.gsap.set(pixels, { display: "none" });
      window.gsap.to(pixels, {
        display: "block",
        duration: 0,
        stagger: { each: staggerTime, from: "random" }
      });

      callTween = window.gsap.delayedCall(duration, () => {
        activeImg.style.display = state ? "block" : "none";
        activeImg.style.pointerEvents = state ? "none" : "";
      });

      window.gsap.to(pixels, {
        display: "none",
        duration: 0,
        delay: duration,
        stagger: { each: staggerTime, from: "random" }
      });
    };

    if (isTouch) {
      item.addEventListener("click", () => toggleReveal(!isActive));
    } else {
      item.addEventListener("mouseenter", () => {
        if (!isActive) toggleReveal(true);
      });
      item.addEventListener("mouseleave", () => {
        if (isActive) toggleReveal(false);
      });
    }
  });
}
